import math

# Diophantine equation derived from Q(1)^2 = Q(0)Q(2) for Q(x) = 64x^3 + a2*x^2 + a1*x - 486
# a1^2 + 2*a1*a2 + a2^2 + 128*a1 + 1100*a2 + 190720 = 0

def check_solution(a1, a2):
    return a1**2 + 2*a1*a2 + a2**2 + 128*a1 + 1100*a2 + 190720 == 0

# Search small integer values for a1 and a2
max_val = 100
solutions = []
for a1 in range(-max_val, max_val + 1):
    for a2 in range(-max_val, max_val + 1):
        if check_solution(a1, a2):
            solutions.append((a1, a2))

print(f"Solutions found in [-100, 100] x [-100, 100]: {solutions}")

